data.value:
CREATE TABLE company_payment_source_versions (
 source_id TEXT NOT NULL, version_id TEXT NOT NULL, source_content_hash TEXT NOT NULL, known_ticks BIGINT NOT NULL,
 PRIMARY KEY(source_id,version_id));
CREATE TABLE company_payment_rows (
 sequence BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 source_id TEXT NOT NULL, source_version_id TEXT NOT NULL, source_row_id TEXT NOT NULL, import_id TEXT NOT NULL,
 payer_company_id UUID NOT NULL, beneficiary_company_id UUID NOT NULL, pay_amt TEXT NOT NULL, pay_cnt TEXT NOT NULL,
 known_ticks BIGINT NOT NULL, row_hash TEXT NOT NULL, payload JSONB NOT NULL,
 UNIQUE(source_id,source_version_id,source_row_id),
 FOREIGN KEY(source_id,source_version_id) REFERENCES company_payment_source_versions(source_id,version_id));
CREATE INDEX ix_payment_payer_asof ON company_payment_rows(source_id,source_version_id,payer_company_id,known_ticks);
CREATE INDEX ix_payment_beneficiary_asof ON company_payment_rows(source_id,source_version_id,beneficiary_company_id,known_ticks);
CREATE INDEX ix_payment_known_ticks ON company_payment_rows(known_ticks DESC);
